mapper.select:
select 
from arc_borrow b
join arc_archive a on a.archive_id = b.archive_id

    and b.applicant_id = #{userId}
    and b.borrow_no like concat('%',#{borrowNo},'%')
    and a.title like concat('%',#{archiveTitle},'%')
    and b.applicant_name like concat('%',#{applicantName},'%')
    and b.borrow_status = #{borrowStatus}
    and b.end_date >= #{dateFrom}
    and b.end_date <= #{dateTo}

order by b.create_time desc, b.borrow_id desc

select archive_id, archive_code, title, archive_status from arc_archive where del_flag = '0' and archive_status in ('SUBMITTED','ARCHIVED')
and (title like concat('%',#{keyword},'%') or archive_code like concat('%',#{keyword},'%'))
order by create_time desc limit #{limit}

mapper.update:
update arc_borrow
set borrow_status = #{to}, update_by = #{operator}, update_time = now(), version = version + 1
where borrow_id = #{borrowId} and borrow_status = #{from}
